<script>
/* ============================================================
   COIN RENDERER — procedural 3D coin in 2D canvas
   Uses raytraced ellipsoid + procedural emboss + specular
   ============================================================ */

const CoinRenderer = (() => {
  // Mulberry32 deterministic PRNG for stable noise
  function mulberry32(a) {
    return function() {
      a |= 0; a = a + 0x6D2B79F5 | 0;
      let t = a;
      t = Math.imul(t ^ t >>> 15, t | 1);
      t ^= t + Math.imul(t ^ t >>> 7, t | 61);
      return ((t ^ t >>> 14) >>> 0) / 4294967296;
    };
  }

  // High-detail value noise for emboss heightfield
  function makeNoise2D(seed) {
    const rand = mulberry32(seed);
    const size = 256;
    const perm = new Uint8Array(size * 2);
    for (let i = 0; i < size; i++) perm[i] = i;
    for (let i = size - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [perm[i], perm[j]] = [perm[j], perm[i]];
    }
    for (let i = 0; i < size; i++) perm[size + i] = perm[i];

    function fade(t) { return t * t * t * (t * (t * 6 - 15) + 10); }
    function lerp(a, b, t) { return a + t * (b - a); }
    function grad(h, x, y) {
      const u = (h & 1) === 0 ? x : -x;
      const v = (h & 2) === 0 ? y : -y;
      return u + v;
    }
    return function(x, y) {
      const X = Math.floor(x) & 255, Y = Math.floor(y) & 255;
      x -= Math.floor(x); y -= Math.floor(y);
      const u = fade(x), v = fade(y);
      const A = perm[X] + Y, B = perm[X + 1] + Y;
      return lerp(
        lerp(grad(perm[A], x, y), grad(perm[B], x - 1, y), u),
        lerp(grad(perm[A + 1], x, y - 1), grad(perm[B + 1], x - 1, y - 1), u),
        v
      );
    };
  }

  // Draw WastedToken emblem (raised relief) into an offscreen canvas,
  // returning it for use as emboss height + albedo
  function drawEmblem(size, label, sub, opts = {}) {
    const c = document.createElement('canvas');
    c.width = c.height = size;
    const ctx = c.getContext('2d');
    ctx.fillStyle = opts.bg || '#000';
    ctx.fillRect(0, 0, size, size);

    const cx = size / 2, cy = size / 2;
    const ringR = size * 0.42;
    const innerR = size * 0.34;

    // Outer ring
    ctx.strokeStyle = opts.ringColor || '#fff';
    ctx.lineWidth = size * 0.012;
    ctx.beginPath();
    ctx.arc(cx, cy, ringR, 0, Math.PI * 2);
    ctx.stroke();

    // Inner ring
    ctx.beginPath();
    ctx.arc(cx, cy, innerR, 0, Math.PI * 2);
    ctx.stroke();

    // Bead ring
    const beadR = size * 0.44;
    const beads = 60;
    for (let i = 0; i < beads; i++) {
      const a = (i / beads) * Math.PI * 2;
      const bx = cx + Math.cos(a) * beadR;
      const by = cy + Math.sin(a) * beadR;
      ctx.beginPath();
      ctx.arc(bx, by, size * 0.005, 0, Math.PI * 2);
      ctx.fillStyle = opts.ringColor || '#fff';
      ctx.fill();
    }

    // Central monogram "WT" stylized
    ctx.save();
    ctx.translate(cx, cy - size * 0.02);
    ctx.fillStyle = opts.fg || '#fff';
    ctx.strokeStyle = opts.fg || '#fff';
    ctx.lineWidth = size * 0.018;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    // W shape
    ctx.beginPath();
    const w = size * 0.06, h = size * 0.13;
    ctx.moveTo(-w, -h);
    ctx.lineTo(-w * 0.4, h);
    ctx.lineTo(0, -h * 0.4);
    ctx.lineTo(w * 0.4, h);
    ctx.lineTo(w, -h);
    ctx.lineWidth = size * 0.022;
    ctx.stroke();

    // T shape under W
    ctx.beginPath();
    ctx.moveTo(-w * 0.8, h * 1.2);
    ctx.lineTo(w * 0.8, h * 1.2);
    ctx.moveTo(0, h * 1.0);
    ctx.lineTo(0, h * 1.8);
    ctx.lineWidth = size * 0.018;
    ctx.stroke();
    ctx.restore();

    // Arc text along top: WT
    ctx.fillStyle = opts.fg || '#fff';
    ctx.font = `bold ${size * 0.045}px Georgia, serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    const textR = size * 0.38;
    const topText = 'WASTED  ✦  TOKEN';
    drawArcText(ctx, topText, cx, cy, textR, -Math.PI / 2, opts.fg || '#fff', size);

    // Bottom: established
    ctx.font = `bold ${size * 0.032}px Georgia, serif`;
    const bottomText = '★  EST · MMXXII  ★';
    drawArcText(ctx, bottomText, cx, cy, textR, Math.PI / 2, opts.fg || '#fff', size);

    // Center sub-text if present
    if (sub) {
      ctx.font = `bold ${size * 0.04}px Georgia, serif`;
      ctx.fillStyle = opts.fg || '#fff';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(sub, cx, cy + size * 0.18);
    }

    return c;
  }

  // Draw back face with denomination
  function drawBack(size, denom, tokenCount, opts = {}) {
    const c = document.createElement('canvas');
    c.width = c.height = size;
    const ctx = c.getContext('2d');
    ctx.fillStyle = opts.bg || '#000';
    ctx.fillRect(0, 0, size, size);

    const cx = size / 2, cy = size / 2;
    const ringR = size * 0.42;
    const innerR = size * 0.34;

    // Outer & inner rings
    ctx.strokeStyle = opts.ringColor || '#fff';
    ctx.lineWidth = size * 0.012;
    ctx.beginPath();
    ctx.arc(cx, cy, ringR, 0, Math.PI * 2);
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(cx, cy, innerR, 0, Math.PI * 2);
    ctx.stroke();

    // Bead ring
    const beadR = size * 0.44;
    for (let i = 0; i < 60; i++) {
      const a = (i / 60) * Math.PI * 2;
      ctx.beginPath();
      ctx.arc(cx + Math.cos(a) * beadR, cy + Math.sin(a) * beadR, size * 0.005, 0, Math.PI * 2);
      ctx.fillStyle = opts.ringColor || '#fff';
      ctx.fill();
    }

    // Center denomination number
    ctx.fillStyle = opts.fg || '#fff';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.font = `bold ${size * 0.16}px Georgia, serif`;
    ctx.fillText(denom, cx, cy - size * 0.04);

    // Label
    ctx.font = `${size * 0.05}px Georgia, serif`;
    ctx.fillText(tokenCount, cx, cy + size * 0.12);

    // Top arc text
    ctx.font = `bold ${size * 0.04}px Georgia, serif`;
    drawArcText(ctx, 'DENOMINATION', cx, cy, size * 0.38, -Math.PI / 2, opts.fg || '#fff', size);

    // Bottom: denomination name
    ctx.font = `bold ${size * 0.032}px Georgia, serif`;
    drawArcText(ctx, `·  ${opts.metalName || 'METAL'} SERIES  ·`, cx, cy, size * 0.38, Math.PI / 2, opts.fg || '#fff', size);

    // Edge stars
    for (let i = 0; i < 8; i++) {
      const a = (i / 8) * Math.PI * 2 + Math.PI / 8;
      const sr = size * 0.28;
      ctx.save();
      ctx.translate(cx + Math.cos(a) * sr, cy + Math.sin(a) * sr);
      ctx.rotate(a);
      ctx.fillStyle = opts.fg || '#fff';
      ctx.beginPath();
      for (let k = 0; k < 5; k++) {
        const sa = (k / 5) * Math.PI * 2 - Math.PI / 2;
        const er = size * 0.012;
        if (k === 0) ctx.moveTo(Math.cos(sa) * er, Math.sin(sa) * er);
        else ctx.lineTo(Math.cos(sa) * er, Math.sin(sa) * er);
        const sa2 = ((k + 0.5) / 5) * Math.PI * 2 - Math.PI / 2;
        ctx.lineTo(Math.cos(sa2) * er * 0.4, Math.sin(sa2) * er * 0.4);
      }
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    }

    return c;
  }

  function drawArcText(ctx, text, cx, cy, radius, startAngle, color, size) {
    const chars = text.split('');
    const totalAngle = (chars.length / 22) * Math.PI; // approximate arc length
    const step = totalAngle / Math.max(1, chars.length - 1);
    for (let i = 0; i < chars.length; i++) {
      const a = startAngle - totalAngle / 2 + i * step;
      const x = cx + Math.cos(a) * radius;
      const y = cy + Math.sin(a) * radius;
      ctx.save();
      ctx.translate(x, y);
      ctx.rotate(a + Math.PI / 2);
      ctx.fillStyle = color;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.font = `bold ${size * 0.04}px Georgia, serif`;
      ctx.fillText(chars[i], 0, 0);
      ctx.restore();
    }
  }

  // Compute lighting for a coin face with given orientation
  // t: animation time [0,1]
  // side: 0 (front), 1 (back)
  // faceImage: ImageData-like canvas
  // returns: rendered Canvas
  function renderCoin(canvas, faceA, faceB, t, metal, opts = {}) {
    const ctx = canvas.getContext('2d');
    const W = canvas.width, H = canvas.height;
    ctx.clearRect(0, 0, W, H);

    // Backdrop
    const bg = ctx.createRadialGradient(W/2, H/2, 0, W/2, H/2, W * 0.6);
    bg.addColorStop(0, opts.bgInner || '#1f1d24');
    bg.addColorStop(1, opts.bgOuter || '#0a0a0c');
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, W, H);

    // Light angle rotates with time so highlight rakes across
    const lightAngle = t * Math.PI * 2;

    // 3D rotation: rotateY about vertical, rotateX about horizontal (flip)
    // We use a parameterization: at t=0..0.5 the coin shows front rotating,
    // at t=0.5 the coin is edge-on, t=0.5..1 shows back rotating,
    // additionally, a flip is interleaved.
    // To make both faces appear and the coin flip:
    //   yaw: continuous rotation about vertical axis (0..2π across t=0..1)
    //   pitch: flip — 0 at t=0, π at t=0.5, 2π at t=1 (so it flips once per loop)
    const yaw = t * Math.PI * 2;
    const pitch = t * Math.PI * 2; // full 360° flip

    // Project the 3D coin (cylinder + reeded edge) onto 2D using parametric points
    const cx = W / 2, cy = H / 2;
    const R = Math.min(W, H) * 0.38; // coin radius
    const thickness = R * 0.13; // edge thickness

    // Cylinder side (reeded edge) parameters
    const reedCount = 90;

    // Compute screen-space coin parameters
    // The visible radius depends on the cos(pitch) - the coin foreshortens on the vertical axis
    // We project using orthographic-ish but with the cylinder math.
    // For a coin oriented by yaw and pitch, the silhouette is an ellipse with:
    //   horizontal radius: R
    //   vertical radius: R * |cos(pitch)| + thickness/2 * |sin(pitch)|
    // We compute proper pixel-by-pixel rendering.

    // Pixel-perfect rendering: iterate rows, find intersections.
    // For each pixel, determine if it's part of the coin, and compute
    // its 3D normal, then shade.

    const imgData = ctx.createImageData(W, H);
    const data = imgData.data;

    // Pre-compute face canvases as ImageData for fast lookup
    const faceDataA = faceA.getContext('2d').getImageData(0, 0, faceA.width, faceA.height);
    const faceDataB = faceB.getContext('2d').getImageData(0, 0, faceB.width, faceB.height);
    const fW = faceA.width, fH = faceA.height;

    // Direction of light
    const Lx = Math.cos(lightAngle);
    const Ly = Math.sin(lightAngle * 0.7) * 0.6 - 0.3;
    const Lz = 0.85; // mostly in front
    const Llen = Math.hypot(Lx, Ly, Lz);
    const lx = Lx / Llen, ly = Ly / Llen, lz = Lz / Llen;

    // View direction (camera)
    const Vx = 0, Vy = 0, Vz = 1;

    // Rotation matrices: apply pitch (about X axis), then yaw (about Y axis)
    // 3D point (px, py, pz) on the coin:
    //   - top face: pz = +thickness/2
    //   - bottom face: pz = -thickness/2
    //   - side: cylinder
    // After pitch (rotation about X by angle p): y' = y*cos(p) - z*sin(p), z' = y*sin(p) + z*cos(p)
    // After yaw (rotation about Y by angle y): x' = x*cos(y) + z*sin(y), z'' = -x*sin(y) + z*cos(y)
    // Visible if z'' > 0 (toward camera)

    const cp = Math.cos(pitch), sp = Math.sin(pitch);
    const cy_ = Math.cos(yaw), sy = Math.sin(yaw);

    // For each pixel, project back to a 3D point on the coin
    // Inverse projection: given screen (sx, sy) and we want to find 3D point on coin
    // Simplified: use the "closest point on coin" approach

    // Pre-compute coin shape parameters
    // The silhouette in screen space is an ellipse with:
    //   center cx, cy
    //   semi-axis a = R (horizontal — yaw doesn't change this for top/bottom faces when looking at flat side)
    // Actually, with full 3D: when pitch=0, the coin is face-on (circle radius R).
    // When pitch=π/2, the coin is edge-on (a thin horizontal bar of length 2R and height thickness).
    // When pitch=π, the coin is face-on again but showing the other side.

    // Let's do it properly with raycasting in screen space.
    // Ray from camera (0,0,0) through pixel direction. We don't need perspective, just orthographic:
    // screen (sx, sy) corresponds to ray direction d = (sx - cx, sy - cy, focal)
    // We need to intersect with the 3D coin (cylinder + two disks).

    // For performance, we'll rasterize the front and back disks directly using
    // a depth+normal approach, then add the reeded edge as a separate step.

    // Method:
    // 1) For each pixel inside the screen-space bounding box of the coin,
    // 2) Determine if it's on top face, bottom face, or edge by projecting
    //    back to the coin's local 3D space.

    // Inverse transform: world (wx, wy, wz) -> local (lx, ly, lz)
    // Apply inverse yaw: lx = wx*cos(-yaw) + wz*sin(-yaw) = wx*cy_ - wz*sy
    //                    lz = -wx*sin(-yaw) + wz*cos(-yaw) = wx*sy + wz*cy_
    // Apply inverse pitch: ly = wy*cos(-pitch) + lz*sin(-pitch) = wy*cp + lz*sp
    //                      lz = -wy*sin(-pitch) + lz*cos(-pitch) = -wy*sp + lz*cp
    // But we go from world (pixel ray) to local — pixel is at (sx - cx, sy - cy, 1) in world (orthographic).
    // After inverse transform, we get the local-space direction of the ray.

    // Easier: parametric approach
    // Local point: (lx, ly, lz). After transform:
    //   wy = ly*cp - lz*sp
    //   wx = lx*cy_ - (ly*sp + lz*cp)*sy
    //   wz = lx*sy + (ly*sp + lz*cp)*cy_
    // We want points where wx = sx - cx, wy = sy - cy, with z toward camera (wz > 0)
    // For orthographic: ray direction in local space is the inverse-transformed (1, 0, 0) and (0, 1, 0).

    // Inverse of [wy = ly*cp - lz*sp; wz = lx*sy + (ly*sp + lz*cp)*cy_]
    // solving for (lx, ly, lz) given (wx, wy, wz) is messy. Let's just iterate analytically.

    // The coin is a cylinder of radius R centered at origin, axis along z, with caps at z=±t/2.
    // After yaw+pitch, the screen position of a point (lx, ly, lz) is:
    //   sx = cx + wx, sy = cy + wy
    // with wx, wy as above.

    // For a given pixel (sx, sy), the ray in world space is direction (1, 0, 0)*du + (0, 1, 0)*dv + (0, 0, 1)
    // i.e., points (du, dv, z) for varying z > 0.
    // We want to find the closest intersection with the coin in world space.
    // The coin occupies the set { (x,y,z) : x²+y² ≤ R², |z| ≤ t/2 } after inverse transform... no wait.
    // The coin in WORLD space (after rotation) is the set of points
    // { M · (lx, ly, lz) : lx²+ly² ≤ R², |lz| ≤ t/2 }
    // where M is the rotation matrix.
    // The pixel ray is { (du, dv, dz) : dz > 0 } parametrized by dz (or some scalar).
    // Find smallest dz such that (du, dv, dz) is in the coin.

    // For orthographic projection, we fix du, dv (= sx-cx, sy-cy) and look for the smallest dz
    // such that the point is on the coin. The point in local coordinates:
    //   (lx, ly, lz) = M^-1 · (du, dv, dz)
    // M = Ry(yaw) · Rx(pitch)
    //   Rx(pitch) = [[1,0,0],[0,cp,-sp],[0,sp,cp]]
    //   Ry(yaw) = [[cy_,0,sy],[0,1,0],[-sy,0,cy_]]
    //   M = Ry · Rx
    //     row0: [cy_, sp*sy, cp*sy]
    //     row1: [0, cp, -sp]
    //     row2: [-sy, sp*cy_, cp*cy_]
    // M^-1 = Rx(-pitch) · Ry(-yaw)
    //   Ry(-yaw) = [[cy_,0,-sy],[0,1,0],[sy,0,cy_]]
    //   Rx(-pitch) = [[1,0,0],[0,cp,sp],[0,-sp,cp]]
    //   M^-1 row0: [cy_, -sy*sp, -sy*cp]  (wait let me recompute)
    //   Let me redo: M^-1 = Rx(-pitch) · Ry(-yaw)
    //   M^-1[0][0] = 1*cy_ + 0*0 + 0*sy = cy_
    //   M^-1[0][1] = 1*0 + 0*1 + 0*0 = 0
    //   M^-1[0][2] = 1*(-sy) + 0*0 + 0*cy_ = -sy
    //   M^-1[1][0] = 0*cy_ + cp*0 + sp*sy = sp*sy
    //   M^-1[1][1] = 0*0 + cp*1 + sp*0 = cp
    //   M^-1[1][2] = 0*(-sy) + cp*0 + sp*cy_ = sp*cy_
    //   M^-1[2][0] = 0*cy_ + (-sp)*0 + cp*sy = cp*sy
    //   M^-1[2][1] = 0*0 + (-sp)*1 + cp*0 = -sp
    //   M^-1[2][2] = 0*(-sy) + (-sp)*0 + cp*cy_ = cp*cy_
    // So local point:
    //   lx = du*cy_ + dv*sp*sy + dz*cp*sy
    //   ly = du*0 + dv*cp + dz*(-sp)
    //       = dv*cp - dz*sp
    //   lz = du*(-sy) + dv*sp*cy_ + dz*cp*cy_
    //      = -du*sy + dv*sp*cy_ + dz*cp*cy_

    // The point is on the coin if lx²+ly² ≤ R² and |lz| ≤ t/2, and we want smallest dz > 0.

    // Hmm this is getting complex. Let me use a different approach:
    // Parametrize each pixel as: in world, pixel center corresponds to plane at z=focal.
    // For orthographic, we just need: given (wx, wy) on screen, find the frontmost point on the rotated coin.
    // The rotated coin is the set { M·p : p in cylinder }. We want the point on the cylinder with maximum
    // z-coordinate (toward camera) that projects to (wx, wy).
    //
    // Alternative: directly iterate over the coin surface (top, bottom, side) and project.

    // Let me use the FORWARD projection: iterate over coin surface elements, project to screen,
    // and write to a z-buffer. This is simpler.

    const zBuf = new Float32Array(W * H);
    const idBuf = new Int32Array(W * H); // which surface
    for (let i = 0; i < zBuf.length; i++) {
      zBuf[i] = -Infinity;
      idBuf[i] = -1;
    }

    // 1) Render top face (lz = +t/2), a disk of radius R
    // Local points: (r*cos(θ), r*sin(θ), t/2)
    // World point after M:
    //   wx = r*cos(θ)*cy_ + r*sin(θ)*sp*sy + (t/2)*cp*sy
    //   wy = r*cos(θ)*0 + r*sin(θ)*cp - (t/2)*sp
    //   wz = -r*cos(θ)*sy + r*sin(θ)*sp*cy_ + (t/2)*cp*cy_

    // 2) Render bottom face (lz = -t/2)
    // 3) Render side (cylinder)

    // Let's sample a grid on each surface
    const N_R = 220; // radial samples
    const N_T = 280; // angular samples

    function plotPixel(sx, sy, wz, id) {
      if (sx < 0 || sx >= W || sy < 0 || sy >= H) return;
      const idx = sy * W + sx;
      if (wz > zBuf[idx]) {
        zBuf[idx] = wz;
        idBuf[idx] = id;
      }
    }

    // Top face
    for (let i = 0; i <= N_R; i++) {
      const r = (i / N_R) * R;
      for (let j = 0; j < N_T; j++) {
        const theta = (j / N_T) * Math.PI * 2;
        const lx = r * Math.cos(theta);
        const ly = r * Math.sin(theta);
        const lz = thickness / 2;
        // Apply M
        const wx = lx * cy_ + ly * sp * sy + lz * cp * sy;
        const wy = ly * cp - lz * sp;
        const wz = -lx * sy + ly * sp * cy_ + lz * cp * cy_;
        plotPixel(Math.round(cx + wx), Math.round(cy + wy), wz, 0);
      }
    }

    // Bottom face
    for (let i = 0; i <= N_R; i++) {
      const r = (i / N_R) * R;
      for (let j = 0; j < N_T; j++) {
        const theta = (j / N_T) * Math.PI * 2;
        const lx = r * Math.cos(theta);
        const ly = r * Math.sin(theta);
        const lz = -thickness / 2;
        const wx = lx * cy_ + ly * sp * sy + lz * cp * sy;
        const wy = ly * cp - lz * sp;
        const wz = -lx * sy + ly * sp * cy_ + lz * cp *cy_;
        plotPixel(Math.round(cx + wx), Math.round(cy + wy), wz, 1);
      }
    }

    // Reeded edge: cylinder with ridges
    for (let j = 0; j < reedCount; j++) {
      const theta = (j / reedCount) * Math.PI * 2;
      // Reeded profile: r varies sinusoidally
      const reedR = R + thickness * 0.04 * Math.sin(theta * 8);
      // Sample along z
      for (let k = 0; k <= 12; k++) {
        const lz = (k / 12 - 0.5) * thickness;
        const lx = reedR * Math.cos(theta);
        const ly = reedR * Math.sin(theta);
        const wx = lx * cy_ + ly * sp * sy + lz * cp * sy;
        const wy = ly * cp - lz * sp;
        const wz = -lx * sy + ly * sp * cy_ + lz * cp * cy_;
        plotPixel(Math.round(cx + wx), Math.round(cy + wy), wz, 2);
      }
    }

    // Now shade each pixel based on its id and 3D normal
    // For top face: normal is M · (0, 0, 1)
    // For bottom face: normal is M · (0, 0, -1)
    // For edge: normal is M · (cos θ, sin θ, 0)
    // Note: the emboss on each face adds heightfield to the normal

    // Pre-compute normals in world space
    const nTop = [cp * sy, -sp, cp * cy_];
    const nBot = [-cp * sy, sp, -cp * cy_];

    // Metal properties
    const baseColor = metal.base; // [r, g, b]
    const specColor = metal.spec; // [r, g, b]
    const shininess = metal.shine;

    function sampleFace(faceData, u, v) {
      // u, v in [0, 1]
      const x = Math.floor(u * (fW - 1));
      const y = Math.floor(v * (fH - 1));
      const idx = (y * fW + x) * 4;
      return [faceData.data[idx], faceData.data[idx+1], faceData.data[idx+2]];
    }

    for (let py = 0; py < H; py++) {
      for (let px = 0; px < W; px++) {
        const idx = py * W + px;
        const id = idBuf[idx];
        if (id < 0) continue;

        let nx, ny, nz;
        let faceU = 0, faceV = 0;
        let faceData;

        if (id === 0 || id === 1) {
          // Top or bottom face
          // Compute local (lx, ly) from world (wx, wy) — we have the pixel center (px, py)
          // Inverse transform: we computed earlier
          const wx = px - cx, wy = py - cy;
          // We need to find which (lx, ly) on the face plane projects here.
          // For top face (lz = t/2):
          //   wx = lx*cy_ + ly*sp*sy + (t/2)*cp*sy
          //   wy = ly*cp - (t/2)*sp
          //   ly = (wy + (t/2)*sp) / cp
          //   lx = (wx - ly*sp*sy - (t/2)*cp*sy) / cy_
          // For bottom: lz = -t/2, similar
          const sign = id === 0 ? 1 : -1;
          const lz = sign * thickness / 2;
          ly = (wy + lz * sp) / cp;
          lx = (wx - ly * sp * sy - lz * cp * sy) / cy_;
          faceU = (lx / R) * 0.5 + 0.5;
          faceV = (ly / R) * 0.5 + 0.5;
          faceData = id === 0 ? faceDataA : faceDataB;

          // Face normal with emboss: we add a small perturbation based on the emboss heightfield
          // Use the gradient of the emboss by sampling neighbors
          nx = id === 0 ? nTop[0] : nBot[0];
          ny = id === 0 ? nTop[1] : nBot[1];
          nz = id === 0 ? nTop[2] : nBot[2];

          // Sample emboss height at center, plus small offsets to get gradient
          const eps = 0.004;
          const h0 = sampleEmboss(faceData, faceU, faceV, fW, fH);
          const hx = sampleEmboss(faceData, faceU + eps, faceV, fW, fH);
          const hy = sampleEmboss(faceData, faceU, faceV + eps, fW, fH);
          const dx = (hx - h0) / eps * 0.3;
          const dy = (hy - h0) / eps * 0.3;
          // Perturb normal in tangent plane
          // Tangent u direction in world: derivative of M·(1,0,0) wrt u*scale
          // For top face, tangent_u = M·(1,0,0) (normalized), tangent_v = M·(0,1,0)
          // Adjust normal: n' = n - dx*tangent_u - dy*tangent_v, then normalize
          const tux = cy_, tuy = 0, tuz = -sy;
          const tvx = sp * sy, tvy = cp, tvz = sp * cy_;
          nx -= dx * tux + dy * tvx;
          ny -= dx * tuy + dy * tvy;
          nz -= dx * tuz + dy * tvz;
          const nl = Math.hypot(nx, ny, nz);
          nx /= nl; ny /= nl; nz /= nl;
        } else {
          // Edge
          // Determine theta from world position
          const wx = px - cx, wy = py - cy;
          // Inverse: lx, ly, lz
          // We know lz varies along the edge; we need the (lx, ly) which is on the cylinder
          // The cylinder points are: (R*cos θ, R*sin θ, lz) after rotation
          // In world: (wx, wy, wz) = M·(R cos θ, R sin θ, lz)
          // We can find θ by looking at the cross product of (wx, wy) with the rotated axes
          // For pitch=0: wx = R cos θ cos yaw, wy = R sin θ
          //   => tan θ = wy / (wx / cos yaw) when cos yaw ≠ 0
          // General: M·(cos θ, sin θ, 0) = (cos θ * cy_ + sin θ * sp * sy, sin θ * cp, -cos θ * sy + sin θ * sp * cy_)
          // We can find θ by atan2 of appropriate combinations
          // The local x-axis (in world): (cy_, 0, -sy)
          // The local y-axis (in world): (sp*sy, cp, sp*cy_)
          // The local z-axis (in world): (cp*sy, -sp, cp*cy_)
          // For a point (R cos θ, R sin θ, lz) in local, world position has:
          //   dot with local_x = wx*cy_ + wy*0 + wz*(-sy)  (but we use orthographic, no z)
          // Hmm, with orthographic we lose z info. Let's just use:
          //   lx = wx*cy_ + 0 + wz*(-sy)  (with wz = depth, unknown from screen)
          // Better approach: since we have idBuf indicating edge, and the point is on the cylinder
          // of radius R, we can find θ by:
          //   The local x and y coords of the surface point are (R cos θ, R sin θ).
          //   We can recover them as: lx = dot(world_point, world_local_x_axis) - lz*dot(local_z, world_local_x_axis)
          // But we don't have lz directly. However, for a given pixel on the edge, lz is constrained by the
          // edge's z extent. Let's just use approximation: assume the edge pixel is at lz=0 (center)
          // and compute θ from that. Then apply reed profile.
          // Actually, for a cleaner approach: project the screen position onto the local xy plane.
          // The 2D screen position is (wx, wy). In local coordinates, this is the projection of
          // (lx, ly, lz) onto the local xy plane, accounting for the rotation.
          // For orthographic projection (z discarded):
          //   wx = lx*cy_ + ly*sp*sy + lz*cp*sy
          //   wy = ly*cp - lz*sp
          // We have 2 equations, 3 unknowns. The cylinder constraint is lx² + ly² = R² (or R_reed).
          // We can solve: pick a lz, find lx, ly.
          // But we need to choose lz such that the world z is maximized (or use the center lz=0).
          // For shading purposes, using lz=0 is fine.
          const lz0 = 0;
          // Solve for ly: wy = ly*cp - lz0*sp => ly = wy/cp
          ly = wy / cp;
          // Solve for lx: wx = lx*cy_ + ly*sp*sy + lz0*cp*sy => lx = (wx - ly*sp*sy)/cy_
          lx = (wx - ly * sp * sy) / cy_;
          // Now (lx, ly) is on/near the cylinder. Compute θ.
          const theta = Math.atan2(ly, lx);
          // Reeded normal: bump out
          const reedBump = 0.15 * Math.sin(theta * 8);
          // Local normal: (cos θ, sin θ, 0) (cylinder) — modified by reed
          // For reeded, the radial normal has a small z component from the ridge
          const nlx = Math.cos(theta);
          const nly = Math.sin(theta);
          const nlz = reedBump;
          const nll = Math.hypot(nlx, nly, nlz);
          const localNx = nlx / nll, localNy = nly / nll, localNz = nlz / nll;
          // Transform to world: M · (localNx, localNy, localNz)
          nx = localNx * cy_ + localNy * sp * sy + localNz * cp * sy;
          ny = localNy * cp - localNz * sp;
          nz = -localNx * sy + localNy * sp * cy_ + localNz * cp * cy_;

          faceU = 0; faceV = 0;
          faceData = faceDataA;
        }

        // Lighting: ambient + diffuse + specular (Blinn-Phong)
        const diff = Math.max(0, nx * lx + ny * ly + nz * lz);
        // Half vector
        const hx = lx + Vx, hy = ly + Vy, hz = lz + Vz;
        const hl = Math.hypot(hx, hy, hz);
        const nhx = hx/hl, nhy = hy/hl, nhz = hz/hl;
        const spec = Math.pow(Math.max(0, nx*nhx + ny*nhy + nhz*nhz), shininess);

        // Fresnel-ish rim
        const fres = Math.pow(1 - Math.max(0, nz), 3);

        // Sample face color
        let baseR, baseG, baseB;
        if (id === 0 || id === 1) {
          const fc = sampleFace(faceData, faceU, faceV);
          // fc is grayscale-ish; tint with metal color
          const lum = (fc[0] + fc[1] + fc[2]) / (3 * 255);
          // The emblem color influences albedo
          // For metals, the albedo is the metal color modulated by the relief (darker in crevices)
          baseR = baseColor[0] * (0.5 + 0.5 * lum);
          baseG = baseColor[1] * (0.5 + 0.5 * lum);
          baseB = baseColor[2] * (0.5 + 0.5 * lum);
        } else {
          // Edge — reeded, use metal base
          // Reeded color varies by theta
          const theta = Math.atan2(ly, lx);
          const reedShade = 0.85 + 0.15 * Math.sin(theta * 8);
          baseR = baseColor[0] * reedShade;
          baseG = baseColor[1] * reedShade;
          baseB = baseColor[2] * reedShade;
        }

        // Ambient occlusion for crevices (using emboss)
        let ao = 1.0;
        if (id === 0 || id === 1) {
          const h = sampleEmboss(faceData, faceU, faceV, fW, fH);
          ao = 0.7 + 0.3 * h; // crevices are darker
        }

        // Compose
        const ambF = 0.18;
        const diffF = 0.55 * diff * ao;
        const specF = spec * 0.9;
        const fresF = fres * 0.25;

        let r = baseR * (ambF + diffF) + specColor[0] * specF + baseR * fresF;
        let g = baseG * (ambF + diffF) + specColor[1] * specF + baseG * fresF;
        let b = baseB * (ambF + diffF) + specColor[2] * specF + baseB * fresF;

        // Subtle radial darkening for vignette on face
        if (id === 0 || id === 1) {
          const cxL = faceU - 0.5, cyL = faceV - 0.5;
          const r2 = cxL*cxL + cyL*cyL;
          const vig = 1 - Math.min(1, r2 * 1.2) * 0.4;
          r *= vig; g *= vig; b *= vig;
        }

        // Slight color burn for shadowed sides
        // (omitted)

        const ii = idx * 4;
        data[ii] = Math.max(0, Math.min(255, r * 255));
        data[ii+1] = Math.max(0, Math.min(255, g * 255));
        data[ii+2] = Math.max(0, Math.min(255, b * 255));
        data[ii+3] = 255;
      }
    }

    // Fill in small gaps with smoothing (single pass)
    // Skipped for performance

    // Soft drop shadow on backdrop
    ctx.putImageData(imgData, 0, 0);
    // shadow
    ctx.save();
    ctx.globalCompositeOperation = 'multiply';
    const sg = ctx.createRadialGradient(cx + R*0.15, cy + R*0.2, 0, cx, cy, R*1.1);
    sg.addColorStop(0, 'rgba(0,0,0,0)');
    sg.addColorStop(0.85, 'rgba(0,0,0,0)');
    sg.addColorStop(1, 'rgba(0,0,0,0.55)');
    ctx.fillStyle = sg;
    ctx.fillRect(0, 0, W, H);
    ctx.restore();

    // Re-stamp the coin pixels on top (multiply blended)
    // Actually the multiply will darken the coin too — skip.
  }

  // Sample emboss height (0..1) from face ImageData (using luminance)
  function sampleEmboss(faceData, u, v, fW, fH) {
    u = Math.max(0, Math.min(0.999, u));
    v = Math.max(0, Math.min(0.999, v));
    const x = Math.floor(u * fW);
    const y = Math.floor(v * fH);
    const idx = (y * fW + x) * 4;
    // Emboss: high values (white in emblem) = raised
    return faceData.data[idx] / 255;
  }

  // Build the 4 metal face canvases
  function buildFaces(metal) {
    const sz = 512;
    const front = drawEmblem(sz, 'WASTED', 'TOKEN', {
      bg: '#000',
      fg: '#fff',
      ringColor: '#fff'
    });
    const back = drawBack(sz, metal.denom, metal.tokenLabel, {
      bg: '#000',
      fg: '#fff',
      ringColor: '#fff',
      metalName: metal.name
    });
    return { front, back };
  }

  return {
    renderCoin,
    buildFaces,
    drawEmblem,
    drawBack
  };
})();

